using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class AtelierPreview {
 static double next;static AtelierPreview(){EditorApplication.update+=Poll;}
 public static void Run(){EditorSceneManager.OpenScene(AtelierEditor.Scene);SessionState.SetBool("Atelier.Preview",true);SessionState.SetInt("Atelier.Step",0);var gv=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView"));gv.Show();gv.maximized=true;gv.Focus();EditorApplication.EnterPlaymode();next=EditorApplication.timeSinceStartup+5;}
 static void Poll(){if(!SessionState.GetBool("Atelier.Preview",false)||!EditorApplication.isPlaying||EditorApplication.isCompiling)return;EditorApplication.QueuePlayerLoopUpdate();UnityEditorInternal.InternalEditorUtility.RepaintAllViews();if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+2;var x=UnityEngine.Object.FindObjectOfType<AtelierExperience>();if(!x||!x.assembly.canvas)return;int step=SessionState.GetInt("Atelier.Step",0);try{switch(step){case 0:x.assembly.effects.fireEnabled=true;next=EditorApplication.timeSinceStartup+5;break;case 1:ScreenCapture.CaptureScreenshot(AtelierEditor.Root+"/Reports/01-workbench.png");break;case 2:x.SetView(1);break;case 3:ScreenCapture.CaptureScreenshot(AtelierEditor.Root+"/Reports/02-front-detail.png");break;case 4:x.engine.principle=true;x.engine.ApplyPose();x.SetView(3);break;case 5:ScreenCapture.CaptureScreenshot(AtelierEditor.Root+"/Reports/03-cutaway.png");break;case 6:x.engine.principle=false;x.engine.ApplyPose();x.engine.GetComponent<LocomotiveDoorsV11>().OpenAll();x.SetView(2);break;case 7:ScreenCapture.CaptureScreenshot(AtelierEditor.Root+"/Reports/04-interior.png");break;case 8:x.engine.GetComponent<LocomotiveDoorsV11>().CloseAll();x.SetView(0);SessionState.SetBool("Atelier.Preview",false);File.WriteAllText(AtelierEditor.Root+"/Reports/preview-complete.txt","Preview complete");break;}SessionState.SetInt("Atelier.Step",step+1);}catch(Exception e){File.WriteAllText(AtelierEditor.Root+"/Reports/preview-error.txt",e.ToString());SessionState.SetBool("Atelier.Preview",false);}}
}
